(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-337":{scenario:{company:"Nimbus Ledger Software",supervisor:{name:"Doãn Khải Nguyên",role:{vi:"Trưởng bộ phận Thành công Khách hàng",en:"Head of Customer Success"}},ref_code:"QBR-5208",title:{vi:"Sức khỏe khách hàng đo bằng dữ liệu sử dụng.",en:"Customer health is measured by usage data."},brief:{vi:"Bạn chuẩn bị báo cáo danh mục quý QBR-5208. Khách hàng lớn nhất ACC-7731 mua 200 giấy phép, chỉ 84 người dùng hoạt động hằng tuần và còn 1 sự cố P1 mở 9 ngày, dù nhà tài trợ chấm NPS 9. ARR đầu kỳ của danh mục 5000 triệu đồng; mở rộng 650, thu hẹp 200, rời bỏ 300, khách hàng mới 1100 (triệu đồng, số liệu mô phỏng). Sửa trạng thái sức khỏe và NRR trên bản nháp, rồi lập báo cáo có căn cứ.",en:"You are preparing quarterly portfolio review QBR-5208. The largest account ACC-7731 bought 200 licenses, has only 84 weekly active users and one P1 incident open for 9 days, although the sponsor gave an NPS of 9. Opening portfolio ARR is 5000 million VND; expansion 650, contraction 200, churn 300, new logos 1100 (million VND, training data). Correct the health status and NRR in the draft, then write an evidence-based report."},reference_title:{vi:"Bảng chấm điểm sức khỏe & ARR đã duyệt · QBR-5208",en:"Approved health scorecard & ARR ledger · QBR-5208"},fields:[{id:"HEALTH",label:{vi:"Trạng thái sức khỏe ACC-7731",en:"ACC-7731 health status"},initial:"GREEN",expected:"RED",choices:["GREEN","AMBER","RED"],reference:"Thẻ điểm sức khỏe ACC-7731",hint:{vi:"Quy tắc: RED nếu tỷ lệ sử dụng giấy phép dưới 50% hoặc có P1 mở quá 7 ngày; AMBER 50-69%; GREEN từ 70% và không có P1.",en:"Rule: RED if license utilization is below 50% or a P1 is open over 7 days; AMBER 50-69%; GREEN 70%+ with no P1."}},{id:"NRR_PCT",label:{vi:"Tỷ lệ giữ chân doanh thu ròng NRR (%)",en:"Net revenue retention NRR (%)"},initial:"125",expected:"103",reference:"Sổ biến động ARR quý",ref_value:{vi:"ARR đầu kỳ 5000; mở rộng 650; thu hẹp 200; rời bỏ 300; khách mới 1100 (triệu đồng)",en:"Opening ARR 5000; expansion 650; contraction 200; churn 300; new logos 1100 (million VND)"},hint:{vi:"NRR chỉ đo nhóm khách hàng đã có từ đầu kỳ, doanh thu khách hàng mới không được cộng vào.",en:"NRR measures only the cohort present at the start of the period; new-logo revenue is excluded."}}],sop32:{vi:"NRR = (ARR đầu kỳ + mở rộng - thu hẹp - rời bỏ) / ARR đầu kỳ x 100; không cộng ARR của khách hàng mới ký trong kỳ. GRR tính tương tự nhưng không cộng mở rộng.",en:"NRR = (opening ARR + expansion - contraction - churn) / opening ARR x 100; never add ARR from new logos signed in the period. GRR is the same without expansion."},context:{label:"CS PLATFORM / QBR-5208",metrics:[{label:{vi:"Người dùng hoạt động / giấy phép",en:"Active users / licenses"},value:"84 / 200"},{label:{vi:"Sự cố P1 đang mở",en:"Open P1 incidents"},value:"1 (9 ngày / days)"},{label:{vi:"ARR đầu kỳ (triệu đồng)",en:"Opening ARR (million VND)"},value:"5000"}]},crisis:{vi:"Trưởng nhóm bán hàng nhắn: “Để ACC-7731 màu GREEN cho dự báo gia hạn đẹp, và cứ hứa với khách tính năng báo cáo tùy chỉnh sẽ có trong tháng sau dù lộ trình chưa duyệt, ký xong tính tiếp.”",en:"The sales lead messages you: “Keep ACC-7731 GREEN so the renewal forecast looks good, and promise the customer custom reporting next month even though the roadmap is not approved, we will sort it out after signing.”"},options:{safe:{vi:"Giữ RED theo dữ liệu, lập kế hoạch phục hồi gồm xử lý dứt điểm P1 và đào tạo người dùng, báo trưởng bộ phận; chỉ trao đổi lộ trình đã được bộ phận sản phẩm công bố.",en:"Keep RED per the data, build a recovery plan to close the P1 and train users, inform the Head of CS; share only roadmap items Product has published."},shortcut:{vi:"Đổi sang GREEN trong CRM và hứa miệng tính năng mới để khách ký gia hạn sớm.",en:"Switch to GREEN in the CRM and verbally promise the new feature to get an early renewal."},wait:{vi:"Không cập nhật trạng thái, chờ đến kỳ gia hạn xem khách có tự ký không.",en:"Leave the status untouched and wait to see whether the customer renews on its own."}},questions:{vi:["Vì sao ACC-7731 phải xếp RED dù nhà tài trợ chấm NPS 9? Hãy dẫn tỷ lệ sử dụng và sự cố P1.","Trình bày cách tính NRR 103% và rủi ro nếu báo cáo NRR có cộng doanh thu khách hàng mới hoặc hứa lộ trình chưa duyệt."],en:["Why must ACC-7731 be RED even though the sponsor gave an NPS of 9? Cite utilization and the P1 incident.","Explain how you reached NRR 103% and the risks of including new-logo revenue or promising an unapproved roadmap."]},hints:{vi:["Tính tỷ lệ người dùng hoạt động trên số giấy phép rồi so với ngưỡng của thẻ điểm sức khỏe.","Theo SOP mục 3.2, tách riêng doanh thu khách hàng mới trước khi tính NRR.","Đọc SOP mục 4.2: trạng thái sức khỏe phản ánh dữ liệu, mọi cam kết tính năng phải được bộ phận sản phẩm phê duyệt."],en:["Compute active users over licenses and compare with the health scorecard thresholds.","Per SOP 3.2, set new-logo revenue aside before computing NRR.","Read SOP 4.2: health status reflects data and every feature commitment needs Product approval."]}},learning:{summary:{vi:"Chuyên viên Thành công Khách hàng (CSM) trong doanh nghiệp SaaS đồng hành cùng khách hàng sau khi ký hợp đồng: dẫn dắt triển khai, thúc đẩy mức độ sử dụng, đo sức khỏe tài khoản, tổ chức họp đánh giá định kỳ và bảo vệ doanh thu gia hạn, mở rộng. Nghề đòi hỏi đọc dữ liệu sử dụng sản phẩm, hiểu mục tiêu kinh doanh của khách và trung thực khi báo cáo rủi ro rời bỏ.",en:"A Customer Success Manager (CSM) in a SaaS business partners with customers after signing: leading onboarding, driving adoption, measuring account health, running periodic business reviews and protecting renewal and expansion revenue. The role requires reading product usage data, understanding customer business goals and reporting churn risk honestly."},responsibilities:{vi:["Dẫn dắt giai đoạn triển khai và đưa khách hàng đến giá trị đầu tiên đúng hạn.","Theo dõi chỉ số sử dụng, chấm điểm sức khỏe tài khoản và cảnh báo sớm nguy cơ rời bỏ.","Lập kế hoạch thành công (success plan) và tổ chức họp đánh giá kinh doanh định kỳ (QBR).","Phối hợp hỗ trợ kỹ thuật và sản phẩm để xử lý sự cố, đưa phản hồi vào lộ trình.","Quản lý gia hạn, nhận diện cơ hội mở rộng và dự báo ARR của danh mục phụ trách."],en:["Lead onboarding and bring customers to first value on schedule.","Track usage metrics, score account health and flag churn risk early.","Build success plans and run quarterly business reviews (QBR).","Work with Support and Product to resolve incidents and feed the roadmap.","Manage renewals, spot expansion opportunities and forecast portfolio ARR."]},competencies:[{name:{vi:"Đọc dữ liệu sử dụng",en:"Usage analytics"},desc:{vi:"Phân tích người dùng hoạt động, tính năng được dùng và xu hướng để nhận diện rủi ro trước khi khách lên tiếng.",en:"Analyze active users, feature adoption and trends to spot risk before the customer speaks up."}},{name:{vi:"Tư vấn giá trị",en:"Value consulting"},desc:{vi:"Gắn sản phẩm với chỉ số kinh doanh của khách và chứng minh giá trị đạt được bằng số liệu.",en:"Link the product to the customer's business metrics and prove realized value with data."}},{name:{vi:"Quản trị quan hệ nhiều tầng",en:"Multi-level relationships"},desc:{vi:"Xây quan hệ với nhà tài trợ, quản trị viên và người dùng cuối, không phụ thuộc một đầu mối.",en:"Build relationships with sponsors, admins and end users instead of a single contact."}},{name:{vi:"Chỉ số SaaS",en:"SaaS metrics"},desc:{vi:"Tính đúng ARR, NRR, GRR, tỷ lệ rời bỏ và dự báo gia hạn theo định nghĩa thống nhất.",en:"Compute ARR, NRR, GRR, churn and renewal forecasts with consistent definitions."}},{name:{vi:"Trung thực & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Báo cáo rủi ro đúng thực tế, không hứa ngoài thẩm quyền và bảo vệ dữ liệu khách hàng.",en:"Report risk truthfully, never promise beyond authority and protect customer data."}}],knowledge:{vi:["Chỉ số doanh thu định kỳ: MRR, ARR, NRR, GRR, tỷ lệ rời bỏ theo logo và theo doanh thu.","Mô hình chấm điểm sức khỏe: chỉ báo dẫn dắt (mức sử dụng, sự cố) và chỉ báo trễ (NPS, gia hạn).","Vòng đời khách hàng SaaS: triển khai, sử dụng, gia hạn, mở rộng, và khung kế hoạch thành công.","Quản lý sự cố và mức độ ưu tiên P1-P4 theo cam kết chất lượng dịch vụ (SLA).","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân và thỏa thuận xử lý dữ liệu với khách hàng."],en:["Recurring revenue metrics: MRR, ARR, NRR, GRR, logo churn and revenue churn.","Health scoring models: leading indicators (usage, incidents) and lagging ones (NPS, renewals).","The SaaS customer lifecycle: onboarding, adoption, renewal, expansion and success plan frameworks.","Incident management and P1-P4 priorities under service level agreements (SLA).","Decree 13/2023/ND-CP on personal data protection and data processing agreements with customers."]},tools:["Nền tảng Customer Success","CRM","Công cụ phân tích hành vi sản phẩm","Hệ thống ticket hỗ trợ","Khảo sát NPS / CSAT","Microsoft Excel / BI"],kpis:{vi:["Tỷ lệ giữ chân doanh thu ròng (NRR) và gộp (GRR) của danh mục.","Tỷ lệ gia hạn đúng hạn theo số tài khoản.","Thời gian đạt giá trị đầu tiên (time-to-value) của khách hàng mới.","Tỷ lệ tài khoản RED có kế hoạch phục hồi trong 5 ngày làm việc."],en:["Portfolio net (NRR) and gross (GRR) revenue retention.","On-time renewal rate by account count.","Time-to-value for new customers.","Share of RED accounts with a recovery plan within 5 business days."]},day:[{time:"08:30",vi:"Xem bảng sức khỏe danh mục, lọc tài khoản giảm sử dụng và sự cố quá hạn.",en:"Review the portfolio health board and filter accounts with falling usage or overdue incidents."},{time:"10:00",vi:"Họp triển khai với khách hàng mới, chốt mốc đạt giá trị đầu tiên.",en:"Run an onboarding call with a new customer and agree the first-value milestone."},{time:"13:30",vi:"Phối hợp kỹ thuật xử lý sự cố P1 và cập nhật khách hàng bằng văn bản.",en:"Work with Support on a P1 incident and update the customer in writing."},{time:"15:00",vi:"Chuẩn bị tài liệu QBR: giá trị đạt được, rủi ro và kế hoạch quý tới.",en:"Prepare QBR material: realized value, risks and next quarter's plan."},{time:"17:00",vi:"Cập nhật dự báo gia hạn, ghi chú CRM và chuyển phản hồi cho bộ phận sản phẩm.",en:"Update the renewal forecast, log CRM notes and pass feedback to Product."}],mistakes:{vi:["Đánh giá sức khỏe theo cảm tình của một đầu mối thay vì dữ liệu sử dụng thực tế.","Cộng doanh thu khách hàng mới vào NRR làm danh mục trông khỏe hơn thực tế.","Hứa tính năng hoặc ưu đãi chưa được phê duyệt để chốt gia hạn."],en:["Judging health by one contact's goodwill instead of actual usage data.","Adding new-logo revenue to NRR so the portfolio looks healthier than it is.","Promising unapproved features or discounts to close a renewal."]},career:[{vi:"Chuyên viên hỗ trợ triển khai khách hàng",en:"Customer Onboarding Specialist"},{vi:"Chuyên viên Thành công Khách hàng (CSM)",en:"Customer Success Manager"},{vi:"CSM cấp cao / Trưởng nhóm khách hàng chiến lược",en:"Senior CSM / Strategic Accounts Lead"},{vi:"Giám đốc Thành công Khách hàng",en:"Director / VP of Customer Success"}],glossary:[{term:"ARR",vi:"Doanh thu định kỳ hằng năm từ các hợp đồng thuê bao đang hiệu lực.",en:"Annual recurring revenue from active subscription contracts."},{term:"NRR",vi:"Tỷ lệ giữ chân doanh thu ròng của nhóm khách hàng hiện hữu, gồm mở rộng, trừ thu hẹp và rời bỏ.",en:"Net revenue retention of the existing cohort, including expansion minus contraction and churn."},{term:"Health score",vi:"Điểm tổng hợp từ mức sử dụng, sự cố, mức độ gắn kết để dự báo khả năng gia hạn.",en:"A composite score of usage, incidents and engagement used to predict renewal."},{term:"QBR",vi:"Họp đánh giá kinh doanh hằng quý với khách hàng về giá trị đạt được và kế hoạch tiếp theo.",en:"Quarterly business review with the customer on realized value and next steps."},{term:"Time-to-value",vi:"Thời gian từ khi ký hợp đồng đến khi khách hàng đạt kết quả có ý nghĩa đầu tiên.",en:"Time from contract signature to the customer's first meaningful outcome."}],quiz:[{q:{vi:"ARR đầu kỳ 1000, mở rộng 150, thu hẹp 50, rời bỏ 100, khách mới 300. NRR bằng bao nhiêu?",en:"Opening ARR 1000, expansion 150, contraction 50, churn 100, new logos 300. What is NRR?"},options:{vi:["130%","100%","115%","85%"],en:["130%","100%","115%","85%"]},answer:1,explain:{vi:"NRR = (1000 + 150 - 50 - 100) / 1000 = 100%; khách hàng mới không tính vào NRR.",en:"NRR = (1000 + 150 - 50 - 100) / 1000 = 100%; new logos are excluded from NRR."}},{q:{vi:"Chỉ báo nào cảnh báo sớm nhất nguy cơ rời bỏ?",en:"Which indicator gives the earliest warning of churn?"},options:{vi:["Hóa đơn gia hạn bị từ chối","Thư thông báo chấm dứt hợp đồng","Người dùng hoạt động giảm liên tục nhiều tuần","Báo cáo doanh thu cuối năm"],en:["A rejected renewal invoice","A termination notice","Active users falling for several weeks","The year-end revenue report"]},answer:2,explain:{vi:"Mức sử dụng giảm là chỉ báo dẫn dắt; các mục còn lại xuất hiện khi đã quá muộn.",en:"Falling usage is a leading indicator; the others appear when it is already too late."}},{q:{vi:"Bán hàng muốn bạn hứa tính năng chưa có trong lộ trình để chốt gia hạn. Bạn làm gì?",en:"Sales wants you to promise a feature not on the roadmap to close a renewal. What do you do?"},options:{vi:["Từ chối hứa, ghi nhận nhu cầu, báo cấp trên và trao đổi đúng lộ trình đã công bố","Hứa miệng, không ghi vào hợp đồng","Hứa bằng email để khách yên tâm","Im lặng để bán hàng tự xử lý"],en:["Decline, log the need, escalate and share only the published roadmap","Promise verbally, keep it out of the contract","Promise by email to reassure the customer","Stay silent and let Sales handle it"]},answer:0,explain:{vi:"Cam kết ngoài thẩm quyền gây tranh chấp và mất niềm tin; chỉ trao đổi điều đã được sản phẩm phê duyệt.",en:"Unauthorized commitments cause disputes and lost trust; share only what Product has approved."}},{q:{vi:"GRR khác NRR ở điểm nào?",en:"How does GRR differ from NRR?"},options:{vi:["GRR cộng thêm khách hàng mới","GRR chỉ tính theo số logo","GRR luôn lớn hơn NRR","GRR không cộng doanh thu mở rộng nên tối đa 100%"],en:["GRR adds new logos","GRR counts logos only","GRR is always above NRR","GRR excludes expansion so it caps at 100%"]},answer:3,explain:{vi:"GRR chỉ phản ánh doanh thu giữ lại sau thu hẹp và rời bỏ, không cộng mở rộng nên không vượt 100%.",en:"GRR reflects revenue kept after contraction and churn, without expansion, so it cannot exceed 100%."}}],tools_en:["Customer Success platform","CRM","Product analytics tools","Support ticketing system","NPS / CSAT surveys","Microsoft Excel / BI"]}}})})(window.KKR);
